{
  "openapi": "3.1.1",
  "info": {
    "title": "Coupon Service API",
    "description": "Coupon validation, pricing preview, redemption lifecycle, and policy administration.",
    "version": "v1"
  },
  "paths": {
    "/v1/coupons/preview": {
      "post": {
        "summary": "POST /v1/coupons/preview \u2014 SAVE10 applied",
        "operationId": "post_v1_coupons_preview",
        "description": "AC-1.1: valid coupon returns subtotal, discount, total, and per-line allocations.",
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "example": {
                "code": "SAVE10",
                "customerId": "customer-1",
                "cart": {
                  "lines": [
                    {
                      "lineId": "line-1",
                      "pizzaId": "margherita",
                      "category": "classic",
                      "unitPrice": 9.50,
                      "quantity": 2
                    },
                    {
                      "lineId": "line-2",
                      "pizzaId": "bbq-chicken",
                      "category": "meat",
                      "unitPrice": 12.00,
                      "quantity": 1
                    }
                  ]
                }
              }
            }
          }
        },
        "security": [
          {
            "bearerAuth": []
          }
        ]
      }
    },
    "/v1/health/live": {
      "get": {
        "summary": "GET /v1/health/live",
        "operationId": "get_v1_health_live",
        "description": "Anonymous liveness probe."
      }
    },
    "/v1/health/ready": {
      "get": {
        "summary": "GET /v1/health/ready",
        "operationId": "get_v1_health_ready",
        "description": "Readiness probe \u2014 includes policy repository check."
      }
    },
    "/v1/reservations": {
      "post": {
        "summary": "POST /v1/reservations \u2014 reserve",
        "operationId": "post_v1_reservations",
        "description": "Authoritative re-price and reserve.",
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "example": {
                "code": "SAVE10",
                "orderId": "order-001",
                "customerId": "customer-1",
                "cart": {
                  "lines": [
                    {
                      "lineId": "line-1",
                      "pizzaId": "margherita",
                      "category": "classic",
                      "unitPrice": 9.50,
                      "quantity": 2
                    }
                  ]
                }
              }
            }
          }
        },
        "security": [
          {
            "bearerAuth": []
          }
        ]
      }
    },
    "/v1/reservations/{orderId}/confirm": {
      "post": {
        "summary": "POST /v1/reservations/{orderId}/confirm",
        "operationId": "post_v1_reservations_orderId_confirm",
        "description": "Confirm reservation \u2014 idempotent.",
        "security": [
          {
            "bearerAuth": []
          }
        ]
      }
    },
    "/v1/reservations/{orderId}/release": {
      "post": {
        "summary": "POST /v1/reservations/{orderId}/release",
        "operationId": "post_v1_reservations_orderId_release",
        "description": "Release reservation \u2014 idempotent.",
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "example": {
                "reason": "payment_failed"
              }
            }
          }
        },
        "security": [
          {
            "bearerAuth": []
          }
        ]
      }
    },
    "/v1/admin/policies": {
      "get": {
        "summary": "GET /v1/admin/policies",
        "operationId": "get_v1_admin_policies",
        "description": "List policies.",
        "security": [
          {
            "bearerAuth": []
          }
        ]
      },
      "post": {
        "summary": "POST /v1/admin/policies",
        "operationId": "post_v1_admin_policies",
        "description": "Create policy \u2014 validated against engine manifest.",
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "example": {
                "policyId": "save10",
                "code": "SAVE10",
                "trigger": "code",
                "status": "Active",
                "engineSchema": "1.0",
                "condition": {
                  "gte": [
                    {
                      "fact": "cart.subtotal"
                    },
                    0
                  ]
                },
                "effect": {
                  "percentage": {
                    "value": 10,
                    "of": {
                      "lines": {
                        "where": {
                          "gte": [
                            {
                              "fact": "line.quantity"
                            },
                            1
                          ]
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        },
        "security": [
          {
            "bearerAuth": []
          }
        ]
      }
    },
    "/v1/admin/policies/{policyId}": {
      "get": {
        "summary": "GET /v1/admin/policies/{policyId}",
        "operationId": "get_v1_admin_policies_policyId",
        "description": "Read a policy by id.",
        "security": [
          {
            "bearerAuth": []
          }
        ]
      },
      "put": {
        "summary": "PUT /v1/admin/policies/{policyId}",
        "operationId": "put_v1_admin_policies_policyId",
        "description": "Update policy \u2014 requires If-Match ETag header.",
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "example": {
                "policyId": "save10",
                "code": "SAVE10",
                "status": "Active",
                "engineSchema": "1.0"
              }
            }
          }
        },
        "security": [
          {
            "bearerAuth": []
          }
        ]
      },
      "delete": {
        "summary": "DELETE /v1/admin/policies/{policyId}",
        "operationId": "delete_v1_admin_policies_policyId",
        "description": "Archive policy (soft delete).",
        "security": [
          {
            "bearerAuth": []
          }
        ]
      }
    },
    "/v1/admin/policies/{policyId}/simulate": {
      "post": {
        "summary": "POST /v1/admin/policies/{policyId}/simulate",
        "operationId": "post_v1_admin_policies_policyId_simulate",
        "description": "Dry run against a sample cart \u2014 returns trace.",
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "example": {
                "code": "SAVE10",
                "customerId": "customer-1",
                "cart": {
                  "lines": [
                    {
                      "lineId": "line-1",
                      "pizzaId": "margherita",
                      "category": "classic",
                      "unitPrice": 31.00,
                      "quantity": 1
                    }
                  ]
                }
              }
            }
          }
        },
        "security": [
          {
            "bearerAuth": []
          }
        ]
      }
    },
    "/v1/admin/policies/{policyId}/status": {
      "post": {
        "summary": "POST /v1/admin/policies/{policyId}/status",
        "operationId": "post_v1_admin_policies_policyId_status",
        "description": "Promote lifecycle: Draft, Shadow, Active, Paused, Archived.",
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "example": {
                "status": "Active"
              }
            }
          }
        },
        "security": [
          {
            "bearerAuth": []
          }
        ]
      }
    },
    "/v1/policy-engine/manifest": {
      "get": {
        "summary": "GET /v1/policy-engine/manifest",
        "operationId": "get_v1_policy-engine_manifest",
        "description": "Facts, operators, effects, and limits.",
        "security": [
          {
            "bearerAuth": []
          }
        ]
      }
    },
    "/openapi/v1.json": {
      "get": {
        "summary": "GET /openapi/v1.json",
        "operationId": "get_openapi_v1.json",
        "description": "Live OpenAPI JSON while running in Development."
      }
    }
  },
  "components": {
    "securitySchemes": {
      "bearerAuth": {
        "type": "http",
        "scheme": "bearer",
        "bearerFormat": "JWT"
      }
    }
  }
}

{
  "openapi": "3.1.1",
  "info": {
    "title": "Order API",
    "description": "Checkout stand-in for the pizza ordering platform.",
    "version": "v1"
  },
  "paths": {
    "/v1/pizzas": {
      "get": {
        "summary": "GET /v1/pizzas",
        "operationId": "get_v1_pizzas",
        "description": "List available pizzas.",
        "security": [
          {
            "bearerAuth": []
          }
        ]
      }
    },
    "/v1/orders": {
      "post": {
        "summary": "POST /v1/orders \u2014 checkout with coupon",
        "operationId": "post_v1_orders",
        "description": "Submit order; client total is discarded \u2014 server re-prices authoritatively.",
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "example": {
                "couponCode": "SAVE10",
                "cart": {
                  "lines": [
                    {
                      "lineId": "line-1",
                      "pizzaId": "margherita",
                      "category": "classic",
                      "unitPrice": 9.50,
                      "quantity": 2
                    },
                    {
                      "lineId": "line-2",
                      "pizzaId": "bbq-chicken",
                      "category": "meat",
                      "unitPrice": 12.00,
                      "quantity": 1
                    }
                  ]
                }
              }
            }
          }
        },
        "security": [
          {
            "bearerAuth": []
          }
        ]
      }
    },
    "/v1/orders/{orderId}": {
      "get": {
        "summary": "GET /v1/orders/{orderId}",
        "operationId": "get_v1_orders_orderId",
        "description": "Read order by id.",
        "security": [
          {
            "bearerAuth": []
          }
        ]
      }
    },
    "/openapi/v1.json": {
      "get": {
        "summary": "GET /openapi/v1.json",
        "operationId": "get_openapi_v1.json",
        "description": "Live OpenAPI JSON while running in Development."
      }
    }
  },
  "components": {
    "securitySchemes": {
      "bearerAuth": {
        "type": "http",
        "scheme": "bearer",
        "bearerFormat": "JWT"
      }
    }
  }
}
